# Convert raw dicts to CharData objects
def _make_char(raw: dict) -> CharData:
    clips = [ClipData(title=c["title"], duration=c["duration"]) for c in raw["clips"]]
    return CharData(
        id=raw["id"],
        name=raw["name"],
        jp=raw["jp"],
        role=raw["role"],
        grade=raw["grade"],
        technique=raw["technique"],
        affiliation=raw["affiliation"],
        description=raw["description"],
        abilities=raw["abilities"],
        image=raw.get("image", ""),
        color=raw["color"],
        bg_from=raw["bg_from"],
        bg_to=raw["bg_to"],
        glow=raw["glow"],
        clips=clips,
    )


CHARACTERS: list[CharData] = [_make_char(r) for r in CHARACTERS_RAW]
CHAR_MAP: dict[str, CharData] = {c.id: c for c in CHARACTERS}

# ─────────────────────────────────────────────
# State
# ─────────────────────────────────────────────
class State(rx.State):
    char_id: str = "megumi"
    show_bio: bool = False
    playing: str = ""

    @rx.var
    def char(self) -> CharData:
        return CHAR_MAP.get(self.char_id, CHARACTERS[0])

    def pick(self, cid: str):
        self.char_id = cid
        self.show_bio = False
        self.playing = ""

    def toggle_bio(self):
        self.show_bio = not self.show_bio

    def play(self, title: str):
        self.playing = "" if self.playing == title else title


