# ─────────────────────────────────────────────
# Helpers
# ─────────────────────────────────────────────
def _dot() -> rx.Component:
    return rx.box(
        width="5px", height="5px",
        border_radius="50%",
        background=State.char.color,
        box_shadow=State.char.glow,
        flex_shrink="0",
    )


def _divider() -> rx.Component:
    return rx.box(width="1px", height="2rem", background="rgba(255,255,255,0.18)")


# ─────────────────────────────────────────────
# Navbar
# ─────────────────────────────────────────────
def navbar() -> rx.Component:
    return rx.hstack(
        rx.text(
            "Jujutsu Kaisen",
            font_family="Cinzel Decorative",
            font_size="1rem",
            font_weight="700",
            color="#fff",
        ),
        rx.spacer(),
        rx.hstack(
            *[
                rx.text(
                    lnk,
                    font_family="Rajdhani",
                    font_size="0.9rem",
                    font_weight=rx.cond(lnk == "Characters", "700", "500"),
                    color=rx.cond(lnk == "Characters", "#fff", "rgba(255,255,255,0.55)"),
                    cursor="pointer",
                    _hover={"color": "#fff"},
                )
                for lnk in ["Home", "Characters", "Episodes & Info", "About"]
            ],
            gap="1.5rem",
        ),
        width="100%",
        padding="1.1rem 2.5rem",
        position="absolute",
        top="0", left="0",
        z_index="50",
    )


# ─────────────────────────────────────────────
# Character selector tabs
# ─────────────────────────────────────────────
def char_tab(c: CharData) -> rx.Component:
    active = State.char_id == c.id
    return rx.box(
        rx.text(
            c.name.split()[0],
            font_size="0.72rem",
            font_weight="700",
            text_transform="uppercase",
            letter_spacing="0.1em",
            color="#fff",
        ),
        padding="0.45rem 1rem",
        border_radius="2rem",
        cursor="pointer",
        transition="all 0.25s",
        background=rx.cond(active, c.color, "rgba(255,255,255,0.05)"),
        border=rx.cond(
            active,
            f"1px solid {c.color}",
            "1px solid rgba(255,255,255,0.1)",
        ),
        box_shadow=rx.cond(active, f"0 0 16px {c.glow}", "none"),
        on_click=State.pick(c.id),
        _hover={
            "background": c.color,
            "border": f"1px solid {c.color}",
            "box_shadow": f"0 0 14px {c.glow}",
        },
        font_family="Rajdhani",
    )


def selector() -> rx.Component:
    return rx.box(
        rx.flex(
            *[char_tab(c) for c in CHARACTERS],
            gap="0.75rem",
            flex_wrap="wrap",
            justify="center",
            padding="0.85rem 2rem",
        ),
        position="sticky",
        top="0",
        z_index="200",
        background="rgba(8,8,20,0.88)",
        backdrop_filter="blur(18px)",
        border_bottom="1px solid rgba(255,255,255,0.07)",
    )


