    return rx.vstack(
        rx.text(label, font_size="0.62rem", color="rgba(255,255,255,0.4)",
                text_transform="uppercase", letter_spacing="0.1em"),
        rx.text(value, font_size="0.82rem", font_weight="600", color="#fff"),
        gap="0.15rem", align="start",
    )


